function swFormat(ms){
  if(ms<0) ms=0;
  var total=Math.floor(ms/1000);
  var h=Math.floor(total/3600);
  var m=Math.floor((total%3600)/60);
  var s=total%60;
  var mm=ms%1000;
  function p2(x){ return (x<10?'0':'')+x; }
  function p3(x){ x=Math.floor(x); return (x<10?'00':(x<100?'0':''))+x; }
  return (h>0? (p2(h)+':'):'') + p2(m)+':'+p2(s)+'.'+p3(mm);
}
function swLaps(laps){
  if(!laps.length) return { total:0, best:0, worst:0 };
  var total=0,best=laps[0],worst=laps[0];
  for(var i=0;i<laps.length;i++){ total+=laps[i]; if(laps[i]<best) best=laps[i]; if(laps[i]>worst) worst=laps[i]; }
  return { total:total, best:best, worst:worst };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { swFormat:swFormat, swLaps:swLaps };
}
if (typeof window !== 'undefined') {
  window.StopwatchForgePure = { swFormat:swFormat, swLaps:swLaps };
}
